/**
 * Responsive sources for the bundled game art in public/assets/games.
 *
 * The masters are 128x128 PNGs of 7 to 20 KB. The variants are WebP at the widths the pages
 * actually draw (56 to 120 CSS pixels), generated by scripts/assets/optimize-images.mjs. The
 * largest step stays at the master's native 128 px. Higher-density hero screens still need
 * higher-resolution original artwork; upsampling does not add detail.
 */
export const GAME_ART_WIDTHS = [48, 96, 128] as const;

const BUNDLED = /^\/assets\/games\/([a-z0-9-]+)\.png$/;

/** `srcset` for bundled game art, or undefined for anything else (uploads, remote images). */
export function gameArtSrcSet(src: string): string | undefined {
  const match = BUNDLED.exec(src);
  if (!match) return undefined;
  return GAME_ART_WIDTHS.map(
    (width) => `/assets/games/${match[1]}-${width}.webp ${width}w`,
  ).join(', ');
}

/** `sizes` for a square piece of game art drawn at a fixed CSS width. */
export const gameArtSizes = (width: number) => `${width}px`;
